import CryptoKit
import Foundation
import Metal
import Testing
@testable import TUFFEngine

/// Regression against the post-optimization native OptiQ tool-prompt capture,
/// not the publisher INT4 reference. The capture is local and deliberately not
/// regenerated by this test. Set TUFF_FLINT_OPTIQ_REGRESSION=1 to require it.
@Suite(.serialized) struct FlintOptiQRegressionTests {
    // A small allowance for FP16 rounding, not the much larger divergence from
    // routing a different expert. The same-machine chunked/decode comparison
    // observed identical logits and routes; cross-device tolerance is unproven.
    private static let maxLogitError: Float = 0.05
    private static let meanLogitError: Double = 0.005

    private struct LogitErrors {
        var maximum: Float = 0
        var sum: Double = 0
        var count = 0
        var finite = true
        mutating func add(_ actual: Float, _ reference: Float) {
            guard actual.isFinite, reference.isFinite else { finite = false; return }
            let error = abs(actual - reference)
            maximum = max(maximum, error)
            sum += Double(error)
            count += 1
        }
        var passes: Bool {
            finite && count > 0 && maximum <= FlintOptiQRegressionTests.maxLogitError
                && sum / Double(count) <= FlintOptiQRegressionTests.meanLogitError
        }
    }

    private static func sameRoute(_ actual: [UInt32], _ reference: [UInt32]) -> Bool {
        actual.sorted() == reference.sorted()
    }

    @Test func comparisonRejectsPerturbations() {
        var unchanged = LogitErrors()
        unchanged.add(1, 1)
        #expect(unchanged.passes)
        var altered = LogitErrors()
        altered.add(1.125, 1)
        #expect(!altered.passes)
        var nonfinite = LogitErrors()
        nonfinite.add(.nan, 1)
        #expect(!nonfinite.passes)
        #expect(Self.sameRoute([1, 2, 3], [3, 2, 1]))
        #expect(!Self.sameRoute([1, 2, 4], [1, 2, 3]))
    }

    @Test func nativeLogitsAndRoutesMatchSavedOptiQCapture() async throws {
        let env = ProcessInfo.processInfo.environment
        guard env["TUFF_FLINT_OPTIQ_REGRESSION"] == "1" else { return }
        let modelPath = try #require(env["TUFF_FLINT_OUTPUT"])
        let promptPath = try #require(env["TUFF_FLINT_TOOL_REFERENCE"])
        let capture = try #require(env["TUFF_FLINT_OPTIQ_CAPTURE"])
        func checkedData(_ path: String, sha256: String) throws -> Data {
            let data = try Data(contentsOf: URL(fileURLWithPath: path), options: .mappedIfSafe)
            let hash = SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
            try #require(hash == sha256, "Wrong or modified fixture: \(path)")
            return data
        }
        let promptData = try checkedData(promptPath, sha256: "78d4bd15c0c0f239191bd0bf650b2c588350e5ce16a99e1769b8a8b97d55352b")
        _ = try checkedData(modelPath + "/manifest.json", sha256: "add65d7baae0751e57e1f46cf7461da12118e2923ddbdb987e2d5d3fa93ff3ff")
        let referenceLogits = try checkedData(capture + ".logits.f16", sha256: "8504240a8950b21fd0e72f29f5de70e4f8444006841f43b67257cde972452330")
        let referenceRoutes = try checkedData(capture + ".routes.u32", sha256: "b0ba457b1643d0e2a188950500d2ce1be14e23d67a68c60c1e7e1d39269810f3")
        let prompt = try #require(JSONSerialization.jsonObject(with: promptData) as? [String: Any])
        let tokens = try #require(prompt["input_ids"] as? [Int])
        try #require(tokens.count == 136)
        let context = try MetalContext()
        let model = try Model.load(directoryURL: URL(fileURLWithPath: modelPath), device: context.device, expecting: .flint40B)
        let vocabulary = model.config.vocabSize
        let layers = model.config.numLayers - 2
        let topK = model.config.topKExperts
        try #require(vocabulary == 150144 && layers == 47 && topK == 6)
        try #require(referenceLogits.count == tokens.count * vocabulary * 2)
        try #require(referenceRoutes.count == tokens.count * layers * topK * 4)
        let runner = try RealForwardRunner(model: model, context: context, maxContext: 1024,
            runtimeConfiguration: RuntimeConfiguration(forceLogitsHead: true))
        let logits = try #require(context.device.makeBuffer(length: vocabulary * 2, options: .storageModeShared))
        var routes = Array(repeating: UInt32.max, count: tokens.count * layers * topK)
        var position = 0
        runner.debugRouterSink = { layer, indices in
            guard layer >= 2 && layer < model.config.numLayers, indices.count == topK else { return }
            let base = (position * layers + layer - 2) * topK
            for (i, expert) in indices.enumerated() { routes[base + i] = UInt32(expert) }
        }
        var errors = LogitErrors()
        var perturbedErrors = LogitErrors()
        var argmaxMismatches = 0
        for (i, token) in tokens.enumerated() {
            position = i
            try await runner.produce(token: Int32(token), position: i, into: logits)
            let actual = logits.contents().assumingMemoryBound(to: Float16.self)
            var actualBest = -Float.infinity, referenceBest = -Float.infinity
            var actualID = -1, referenceID = -1
            referenceLogits.withUnsafeBytes { bytes in
                for j in 0..<vocabulary {
                    let bits = UInt16(littleEndian: bytes.loadUnaligned(fromByteOffset: (i * vocabulary + j) * 2, as: UInt16.self))
                    let expected = Float(Float16(bitPattern: bits))
                    let value = Float(actual[j])
                    errors.add(value, expected)
                    // Exercise the same full-capture gate with one real native
                    // logit changed, without modifying the runner or fixture.
                    perturbedErrors.add(i == 0 && j == 0 ? value + 1 : value, expected)
                    if value > actualBest { actualBest = value; actualID = j }
                    if expected > referenceBest { referenceBest = expected; referenceID = j }
                }
            }
            if actualID != referenceID { argmaxMismatches += 1 }
        }
        var routeMismatches = 0
        referenceRoutes.withUnsafeBytes { bytes in
            for row in 0..<(tokens.count * layers) {
                let base = row * topK
                let expected = (0..<topK).map { k in
                    UInt32(littleEndian: bytes.loadUnaligned(fromByteOffset: (base + k) * 4, as: UInt32.self))
                }
                if !Self.sameRoute(Array(routes[base..<(base + topK)]), expected) { routeMismatches += 1 }
            }
        }
        print("OptiQ native regression: max logit error \(errors.maximum), mean \(errors.sum / Double(max(errors.count, 1))), argmax mismatches \(argmaxMismatches), route set mismatches \(routeMismatches)")
        model.streamersQueue.sync {
            for (layer, streamer) in model.streamersBox.streamers.enumerated() {
                guard let streamer else { continue }
                let metrics = streamer.readMetrics
                print("OptiQ layer \(layer): demand \(metrics.demandReads) reads \(metrics.demandBytes) bytes; prefetch \(metrics.prefetchReads) reads \(metrics.prefetchBytes) bytes")
            }
        }
        #expect(errors.passes, "Native logits exceed the saved OptiQ capture bounds or are non-finite")
        #expect(!perturbedErrors.passes, "A one-logit native perturbation must fail the same fidelity bounds")
        #expect(argmaxMismatches == 0)
        #expect(routeMismatches == 0)
    }
}
